CREATE TABLE IF NOT EXISTS "hackathon_profiles" ("id" serial PRIMARY KEY NOT NULL, "owner_key" text DEFAULT 'admin' NOT NULL, "name" text NOT NULL, "skills" text[] DEFAULT '{}' NOT NULL, "interests" text[] DEFAULT '{}' NOT NULL, "experience_level" text DEFAULT 'intermediate' NOT NULL, "location" text, "accessibility_needs" text[] DEFAULT '{}' NOT NULL, "preferences" jsonb DEFAULT '{}'::jsonb NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "hackathon_profiles_owner_unique" ON "hackathon_profiles" ("owner_key");
CREATE TABLE IF NOT EXISTS "hackathon_startup_profiles" ("id" serial PRIMARY KEY NOT NULL, "owner_key" text DEFAULT 'admin' NOT NULL, "name" text NOT NULL, "slug" text NOT NULL, "summary" text, "themes" text[] DEFAULT '{}' NOT NULL, "active" boolean DEFAULT true NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "hackathon_startup_profiles_slug_unique" ON "hackathon_startup_profiles" ("slug");
INSERT INTO "hackathon_startup_profiles" ("name","slug","summary","themes") VALUES ('Deborah School','deborah-school','Learning, exam preparation and student outcomes.','{"education","learning","ai"}'),('TenaSew','tenasew','Habits, progress, wellness and guided routines.','{"wellness","habits","ai"}'),('EthioVista','ethiovista','Travel, destinations, stays and trip planning.','{"travel","local commerce","ai"}'),('Negus Gebeya','negus-gebeya','Marketplace, sellers, trust, messaging and payments.','{"marketplace","commerce","payments"}'),('Personal / General','personal-general','A general profile for personal or experimental ideas.','{"software","product","community"}') ON CONFLICT ("slug") DO NOTHING;
CREATE TABLE IF NOT EXISTS "hackathons" ("id" serial PRIMARY KEY NOT NULL, "canonical_url" text NOT NULL, "title" text NOT NULL, "organizer" text NOT NULL, "description" text, "themes" text[] DEFAULT '{}' NOT NULL, "format" text DEFAULT 'unknown' NOT NULL, "location" text, "country_eligibility" text, "eligibility" text DEFAULT 'unknown' NOT NULL, "deadline" timestamptz, "starts_at" timestamptz, "ends_at" timestamptz, "prize" text, "cost" text, "team_requirements" text, "official_url" text NOT NULL, "registration_url" text, "verification_state" text DEFAULT 'unknown' NOT NULL, "verified_at" timestamptz, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "hackathons_canonical_url_unique" ON "hackathons" ("canonical_url");
CREATE INDEX IF NOT EXISTS "hackathons_deadline_idx" ON "hackathons" ("deadline");
CREATE TABLE IF NOT EXISTS "hackathon_evidence" ("id" serial PRIMARY KEY NOT NULL, "hackathon_id" integer NOT NULL REFERENCES "hackathons"("id") ON DELETE CASCADE, "source_url" text NOT NULL, "source_title" text, "publisher" text, "excerpt" text, "captured_at" timestamptz DEFAULT now() NOT NULL, "verification_state" text DEFAULT 'verified' NOT NULL);
CREATE TABLE IF NOT EXISTS "hackathon_matches" ("id" serial PRIMARY KEY NOT NULL, "hackathon_id" integer NOT NULL REFERENCES "hackathons"("id") ON DELETE CASCADE, "profile_id" integer NOT NULL REFERENCES "hackathon_profiles"("id") ON DELETE CASCADE, "startup_profile_id" integer REFERENCES "hackathon_startup_profiles"("id") ON DELETE SET NULL, "score" integer NOT NULL, "breakdown" jsonb DEFAULT '{}'::jsonb NOT NULL, "explanation" text, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "saved_hackathons" ("id" serial PRIMARY KEY NOT NULL, "owner_key" text DEFAULT 'admin' NOT NULL, "hackathon_id" integer NOT NULL REFERENCES "hackathons"("id") ON DELETE CASCADE, "status" text DEFAULT 'Saved' NOT NULL, "notes" text, "application_details" text, "project_idea" text, "team_info" text, "user_deadline" timestamptz, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "saved_hackathons_owner_hackathon_unique" ON "saved_hackathons" ("owner_key","hackathon_id");
CREATE INDEX IF NOT EXISTS "saved_hackathons_status_idx" ON "saved_hackathons" ("owner_key","status");
